dashboard.definition:
{
  "title": "AD Health & Performance",
  "description": "Domain controller health and performance: AD health-check, Netlogon and DNS-health events flagging problems, data freshness per DC, and Perfmon counters for NTDS (LDAP, replication queue, threads), CPU, DNS and DFS replicated folders. Problem events are detected by keywords (macro adx_problem_terms) because the free-text health sources have no fixed schema.",
  "inputs": {
    "input_global_trp": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-7d@h,now"
      }
    },
    "input_pm_st": {
      "type": "input.dropdown",
      "title": "Perfmon sourcetype",
      "options": {
        "token": "pm_st",
        "defaultValue": "Perfmon:NTDS",
        "items": [
          {
            "label": "NTDS",
            "value": "Perfmon:NTDS"
          },
          {
            "label": "DNS",
            "value": "Perfmon:DNS"
          },
          {
            "label": "DFS Replicated Folders",
            "value": "Perfmon:DFS_Replicated_Folders"
          },
          {
            "label": "Network Interface",
            "value": "Perfmon:Network_Interface"
          },
          {
            "label": "Processor",
            "value": "Perfmon:Processor"
          }
        ]
      }
    },
    "input_pm_counter": {
      "type": "input.dropdown",
      "title": "Counter",
      "options": {
        "token": "pm_counter",
        "selectFirstSearchResult": true
      },
      "dataSources": {
        "primary": "ds_counters"
      }
    }
  },
  "defaults": {},
  "visualizations": {
    "viz_1": {
      "type": "splunk.singlevalue",
      "title": "DCs sending health data",
      "dataSources": {
        "primary": "ds_1"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "viz_2": {
      "type": "splunk.singlevalue",
      "title": "Health events flagging a problem",
      "dataSources": {
        "primary": "ds_2"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#FFC300",
            "from": 1,
            "to": 10
          },
          {
            "value": "#B0413E",
            "from": 10
          }
        ]
      }
    },
    "viz_3": {
      "type": "splunk.singlevalue",
      "title": "Netlogon problem events",
      "dataSources": {
        "primary": "ds_3"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#FFC300",
            "from": 1,
            "to": 50
          },
          {
            "value": "#B0413E",
            "from": 50
          }
        ]
      }
    },
    "viz_4": {
      "type": "splunk.singlevalue",
      "title": "DNS health problem events",
      "dataSources": {
        "primary": "ds_4"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#FFC300",
            "from": 1,
            "to": 10
          },
          {
            "value": "#B0413E",
            "from": 10
          }
        ]
      }
    },
    "viz_5": {
      "type": "splunk.singlevalue",
      "title": "Silent sources (no data > 60 min)",
      "dataSources": {
        "primary": "ds_5"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      }
    },
    "viz_6": {
      "type": "splunk.table",
      "title": "Data freshness per DC and source (last event seen)",
      "dataSources": {
        "primary": "ds_6"
      },
      "options": {
        "count": 15,
        "wrap": true
      },
      "description": "Minutes since the last event for each DC and each AD data source. Empty cell = that DC never sent that source in the last 24h."
    },
    "viz_7": {
      "type": "splunk.table",
      "title": "AD health check events flagging a problem",
      "dataSources": {
        "primary": "ds_7"
      },
      "options": {
        "count": 10,
        "wrap": true
      }
    },
    "viz_8": {
      "type": "splunk.table",
      "title": "Netlogon problem events",
      "dataSources": {
        "primary": "ds_8"
      },
      "options": {
        "count": 10,
        "wrap": true
      }
    },
    "viz_9": {
      "type": "splunk.table",
      "title": "DNS health problem events",
      "dataSources": {
        "primary": "ds_9"
      },
      "options": {
        "count": 10,
        "wrap": true
      }
    },
    "viz_10": {
      "type": "splunk.column",
      "title": "Problem events over time by source",
      "dataSources": {
        "primary": "ds_10"
      },
      "options": {
        "legendDisplay": "bottom",
        "stackMode": "stacked"
      }
    },
    "viz_11": {
      "type": "splunk.line",
      "title": "NTDS - LDAP searches/sec",
      "dataSources": {
        "primary": "ds_11"
      },
      "options": {
        "legendDisplay": "bottom"
      }
    },
    "viz_12": {
      "type": "splunk.line",
      "title": "NTDS - pending replication operations",
      "dataSources": {
        "primary": "ds_12"
      },
      "options": {
        "legendDisplay": "bottom"
      }
    },
    "viz_13": {
      "type": "splunk.line",
      "title": "NTDS - DS threads in use",
      "dataSources": {
        "primary": "ds_13"
      },
      "options": {
        "legendDisplay": "bottom"
      }
    },
    "viz_14": {
      "type": "splunk.line",
      "title": "CPU - % Processor Time (_Total)",
      "dataSources": {
        "primary": "ds_14"
      },
      "options": {
        "legendDisplay": "bottom"
      }
    },
    "viz_15": {
      "type": "splunk.line",
      "title": "DNS - queries received/sec",
      "dataSources": {
        "primary": "ds_15"
      },
      "options": {
        "legendDisplay": "bottom"
      }
    },
    "viz_16": {
      "type": "splunk.line",
      "title": "DNS - recursive query failures/sec",
      "dataSources": {
        "primary": "ds_16"
      },
      "options": {
        "legendDisplay": "bottom"
      }
    },
    "viz_17": {
      "type": "splunk.line",
      "title": "Perfmon explorer: pick any counter",
      "dataSources": {
        "primary": "ds_17"
      },
      "options": {
        "legendDisplay": "bottom"
      },
      "description": "Choose a Perfmon sourcetype then a counter (NTDS, DNS, DFS Replicated Folders, Network Interface, Processor)."
    }
  },
  "dataSources": {
    "ds_1": {
      "type": "ds.search",
      "name": "DCs sending health data",
      "options": {
        "query": "`adx_msad_index` sourcetype=\"MSAD:NT6:Health\" | stats dc(host)",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_2": {
      "type": "ds.search",
      "name": "Health events flagging a problem",
      "options": {
        "query": "`adx_msad_index` sourcetype=\"MSAD:NT6:Health\" `adx_problem_terms` | stats count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_3": {
      "type": "ds.search",
      "name": "Netlogon problem events",
      "options": {
        "query": "`adx_msad_index` sourcetype=\"MSAD:NT6:Netlogon\" `adx_problem_terms` | stats count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_4": {
      "type": "ds.search",
      "name": "DNS health problem events",
      "options": {
        "query": "`adx_msad_index` sourcetype=\"MSAD:NT6:DNS-Health\" `adx_problem_terms` | stats count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_5": {
      "type": "ds.search",
      "name": "Silent sources (no data > 60 min)",
      "options": {
        "query": "| multisearch [search `adx_msad_index` (sourcetype=\"MSAD:NT6:Health\" OR sourcetype=\"MSAD:NT6:Replication\" OR sourcetype=\"MSAD:NT6:Netlogon\" OR sourcetype=\"MSAD:NT6:DNS-Health\") | fields host sourcetype _time] [search `adx_perfmon_index` (sourcetype=\"Perfmon:NTDS\" OR sourcetype=\"Perfmon:Processor\") | fields host sourcetype _time] | stats max(_time) as last by host sourcetype | where last<now()-3600 | stats count",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_6": {
      "type": "ds.search",
      "name": "Data freshness per DC and source (last event seen)",
      "options": {
        "query": "| multisearch [search `adx_msad_index` (sourcetype=\"MSAD:NT6:Health\" OR sourcetype=\"MSAD:NT6:Replication\" OR sourcetype=\"MSAD:NT6:Netlogon\" OR sourcetype=\"MSAD:NT6:DNS-Health\") | fields host sourcetype _time] [search `adx_perfmon_index` (sourcetype=\"Perfmon:NTDS\" OR sourcetype=\"Perfmon:Processor\" OR sourcetype=\"Perfmon:DNS\" OR sourcetype=\"Perfmon:DFS_Replicated_Folders\") | fields host sourcetype _time] | stats max(_time) as last by host sourcetype | eval minutes_ago=round((now()-last)/60,0), last=strftime(last,\"%Y-%m-%d %H:%M\"), status=if(minutes_ago>60,\"SILENT\",\"OK\") | chart latest(minutes_ago) as m over host by sourcetype",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_7": {
      "type": "ds.search",
      "name": "AD health check events flagging a problem",
      "options": {
        "query": "`adx_msad_index` sourcetype=\"MSAD:NT6:Health\" `adx_problem_terms` | eval message=substr(_raw,1,400) | sort - _time | table _time host sourcetype message",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_8": {
      "type": "ds.search",
      "name": "Netlogon problem events",
      "options": {
        "query": "`adx_msad_index` sourcetype=\"MSAD:NT6:Netlogon\" `adx_problem_terms` | eval message=substr(_raw,1,400) | sort - _time | table _time host sourcetype message",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_9": {
      "type": "ds.search",
      "name": "DNS health problem events",
      "options": {
        "query": "`adx_msad_index` sourcetype=\"MSAD:NT6:DNS-Health\" `adx_problem_terms` | eval message=substr(_raw,1,400) | sort - _time | table _time host sourcetype message",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_10": {
      "type": "ds.search",
      "name": "Problem events over time by source",
      "options": {
        "query": "`adx_msad_index` (sourcetype=\"MSAD:NT6:Health\" OR sourcetype=\"MSAD:NT6:Netlogon\" OR sourcetype=\"MSAD:NT6:DNS-Health\") `adx_problem_terms` | timechart count by sourcetype",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_11": {
      "type": "ds.search",
      "name": "NTDS - LDAP searches/sec",
      "options": {
        "query": "`adx_perfmon_index` sourcetype=\"Perfmon:NTDS\" counter=\"LDAP Searches/sec\" | timechart span=5m avg(Value) by host limit=15",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_12": {
      "type": "ds.search",
      "name": "NTDS - pending replication operations",
      "options": {
        "query": "`adx_perfmon_index` sourcetype=\"Perfmon:NTDS\" counter=\"DRA Pending Replication Operations\" | timechart span=5m avg(Value) by host limit=15",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_13": {
      "type": "ds.search",
      "name": "NTDS - DS threads in use",
      "options": {
        "query": "`adx_perfmon_index` sourcetype=\"Perfmon:NTDS\" counter=\"DS Threads in Use\" | timechart span=5m avg(Value) by host limit=15",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_14": {
      "type": "ds.search",
      "name": "CPU - % Processor Time (_Total)",
      "options": {
        "query": "`adx_perfmon_index` sourcetype=\"Perfmon:Processor\" counter=\"% Processor Time\" instance=\"_Total\" | timechart span=5m avg(Value) by host limit=15",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_15": {
      "type": "ds.search",
      "name": "DNS - queries received/sec",
      "options": {
        "query": "`adx_perfmon_index` sourcetype=\"Perfmon:DNS\" counter=\"Total Query Received/sec\" | timechart span=5m avg(Value) by host limit=15",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_16": {
      "type": "ds.search",
      "name": "DNS - recursive query failures/sec",
      "options": {
        "query": "`adx_perfmon_index` sourcetype=\"Perfmon:DNS\" counter=\"Recursive Query Failure/sec\" | timechart span=5m avg(Value) by host limit=15",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_17": {
      "type": "ds.search",
      "name": "Perfmon explorer: pick any counter",
      "options": {
        "query": "`adx_perfmon_index` sourcetype=\"$pm_st$\" counter=\"$pm_counter$\" | eval series=host.\" \".coalesce(instance,\"\") | timechart span=5m avg(Value) by series limit=15",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_counters": {
      "type": "ds.search",
      "name": "Perfmon counters",
      "options": {
        "query": "`adx_perfmon_index` sourcetype=\"$pm_st$\" | stats count by counter | eval label=counter, value=counter | sort label | fields label value",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    }
  },
  "layout": {
    "type": "grid",
    "options": {
      "width": 1440,
      "height": 2566,
      "display": "auto-scale"
    },
    "structure": [
      {
        "item": "viz_1",
        "type": "block",
